text:
            .join("REPOSITORY_CONTRACT.yaml"),
    )?;
    let native = native_layout_rules(root);
    if let Some(arr) = c["paths"].as_array_mut() {
        let mut merged = native.clone();
        merged.extend(arr.clone());
        *arr = merged;
    }
    c["capability_roots"] = json!({"native_source": native.iter().filter(|r| r["class"] == "source").map(|r| r["pattern"].clone()).collect::<Vec<_>>(), "native_tests": native.iter().filter(|r| r["class"] == "test").map(|r| r["pattern"].clone()).collect::<Vec<_>>()});
    Ok((c, native))
}

pub fn ensure_roots(root: &Path) -> Result<()> {
    for d in SPEC_DIRS {
        let p = root.join("spec").join(d);
        std::fs::create_dir_all(&p)?;
        let keep = p.join(".gitkeep");
        if !keep.exists() && std::fs::read_dir(&p)?.next().is_none() {
            write_text(&keep, "")?;
        }
    }
    // ARCHIVE_POLICY.archive_root / archive_subdirs decide the archive layout
    let pr = Project::open(root);
    let (archive_root, subdirs): (String, Vec<String>) = if pr.is_installed() {
        let pol = pr.policies();
        let subs = pol.get_list("ARCHIVE_POLICY", "archive_subdirs");
        (
            pol.get_str("ARCHIVE_POLICY", "archive_root", "archive"),
            if subs.is_empty() {
                ARCHIVE_DIRS.iter().map(|s| s.to_string()).collect()
            } else {
                subs
            },
        )
    } else {
        (
            "archive".into(),
            ARCHIVE_DIRS.iter().map(|s| s.to_string()).collect(),
        )
    };
    for d in &subdirs {
        let p = root.join(&archive_root).join(d);
        std::fs::create_dir_all(&p)?;
        let keep = p.join(".gitkeep");
        if !keep.exists() && std::fs::read_dir(&p)?.next().is_none() {
            write_text(&keep, "")?;
        }
    }
    std::fs::create_dir_all(root.join("product"))?;
    std::fs::create_dir_all(root.join("governance").join("generated"))?;
    let tests = root.join("governance").join("tests").join("memory");
    std::fs::create_dir_all(&tests)?;
    let held = tests.join("heldout.yaml");
    if !held.exists() {
        write_yaml(&held, &json!({"version": "1", "queries": []}))?;
    }
    let gi = root.join(".gitignore");
    let mut text = read_text(&gi).unwrap_or_default();
    if !text
        .lines()
        .any(|l| l.trim() == ".governance-runtime/" || l.trim() == ".governance-runtime")
    {
        if !text.is_empty() && !text.ends_with('\n') {
            text.push('\n');
        }
        text.push_str(".governance-runtime/\n");
        write_text(&gi, &text)?;
    }
    let now = root.join("spec").join("now").join("NOW.md");
    if !now.exists() {
        write_text(&now, "# NOW\n\nCurrent focus pointer (narrative, not authoritative). Authoritative state lives in governed records: run `gov status`.\n")?;
    }
    Ok(())
}

